{
  "name": "A2D继电器板",
  "name_en": "A2D Relay Board",
  "manufacturer": "A2D",
  "description": "一款用于实验室自动化的继电器切换板，可控制电源与电子负载的连接状态，并支持多通道切换、板载指示灯控制以及I2C扩展器地址设置。常用于自动测试工装中的电源路径切换与设备联接控制。",
  "description_en": "A relay switching board for laboratory automation that controls the connection state of power supplies and electronic loads. It supports multi-channel switching, onboard LED control, and I2C expander address configuration, and is commonly used for power-path switching and equipment connection control in automated test setups.",
  "tag_hints": [
    "relay switching",
    "power supply routing",
    "electronic load switching",
    "test automation",
    "multi-channel relay board",
    "I2C expander"
  ],
  "actions": [
    {
      "action_name": "auto-connect_eload",
      "description": "连接或断开电子负载。",
      "description_en": "Connect or disconnect the electronic load."
    },
    {
      "action_name": "auto-connect_psu",
      "description": "连接或断开电源。",
      "description_en": "Connect or disconnect the power supply."
    },
    {
      "action_name": "auto-eload_connected",
      "description": "获取电子负载的连接状态。",
      "description_en": "Get the electronic load connection state."
    },
    {
      "action_name": "auto-initialize",
      "description": "初始化继电器板。",
      "description_en": "Initialize the relay board."
    },
    {
      "action_name": "auto-psu_connected",
      "description": "获取电源的连接状态。",
      "description_en": "Get the power supply connection state."
    },
    {
      "action_name": "auto-reset",
      "description": "复位继电器板。",
      "description_en": "Reset the relay board."
    },
    {
      "action_name": "auto-set_i2c_expander_addr",
      "description": "设置I2C扩展器地址。",
      "description_en": "Set the I2C expander address."
    },
    {
      "action_name": "auto-set_led",
      "description": "设置板载LED状态或数值。",
      "description_en": "Set the onboard LED state or value."
    },
    {
      "action_name": "auto-get_num_channels",
      "description": "获取通道数量。",
      "description_en": "Get the number of channels."
    }
  ]
}

